def _graver_planche(c):
    """Grave la planche UNE FOIS par document. Renvoie son nom.
    ⚠️ La marque est posée SUR LE CANEVAS, jamais dans un dictionnaire
    indexé par id() : Python réutilise les id() libérés."""
    nom = "WIN_DECOR"
    if not getattr(c, "_win_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._win_forme_faite = True
    return nom


def _poser_decor(c, x0, y0, couleurs):
    """Tamponne la planche UNE FOIS PAR CARTON, chacun dans SA couleur.
    ⭐ Le dessin n'est gravé qu'une seule fois dans le document ; on le
    repose seize fois en ne laissant voir, à chaque fois, que le carton
    concerné. C'est ce qui rend l'arc-en-ciel carton par carton."""
    nom = _graver_planche(c)
    marge = 0.3 * mm
    for gi, (bord, cadre, _cases, _rangee) in enumerate(CARTES):
        gx = x0 + bord[0] / 1000.0 * FEUILLE_W - marge
        gl = (bord[1] - bord[0]) / 1000.0 * FEUILLE_W + 2 * marge
        gy = y0 + FEUILLE_H - cadre[1] / 1000.0 * FEUILLE_H - marge
        gh = (cadre[1] - cadre[0]) / 1000.0 * FEUILLE_H + 2 * marge
        c.saveState()
        fen = c.beginPath()
        fen.rect(gx, gy, gl, gh)
        c.clipPath(fen, stroke=0, fill=0)
        c.setFillColor(couleurs[gi])
        c.translate(x0, y0)
        c.doForm(nom)
        c.restoreState()


def _gen_grille(rng):
    """NEUF numéros, exactement la règle du WIN.
    col 1 : 1-15 · col 2 : 16-30 · col 3 : 31-45 — trois chacune, triés.
    La grille est pleine, aucune case vide."""
    c1 = sorted(rng.sample(range(1, 16), LIGNES))
    c2 = sorted(rng.sample(range(16, 31), LIGNES))
    c3 = sorted(rng.sample(range(31, 46), LIGNES))
    return [[c1[r], c2[r], c3[r]] for r in range(LIGNES)]


# ⭐ Ce jeu peut fabriquer 455 × 455 × 455 = 94 196 375 cartons différents.
#    C'est très confortable, mais on garde quand même en mémoire, pendant
#    tout le document, les cartons déjà sortis : dans une même rame, aucun
#    doublon possible.
def _tirer(rng, deja):
    for _ in range(400):
        g = _gen_grille(rng)
        cle = tuple(tuple(r) for r in g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g



# ══ 🎲 LE JUMEAU « WIN CASINO » ══════════════════════════════════════
# Le meme jeu, mais les petits numeros (1 a 9) vivent en VRAIS DES.
# Il tourne sur la MEME planche : changer la maquette du WIN change aussi
# celle du WIN CASINO. Les des sont simplement remis a l'echelle de ses
# nouvelles cases.
_DECOMP_DES = {7: (4, 3), 8: (4, 4), 9: (5, 4)}


def _un_de(c, cx, cy, t, valeur, col, gris_ch):
    """Un vrai de : carre arrondi blanc borde couleur, points gris disposes
    comme sur les des du commerce."""
    r = t / 2.0
    c.setStrokeColor(col)
    c.setLineWidth(max(0.6, t * 0.035))
    c.setFillColor(colors.white)
    c.roundRect(cx - r, cy - r, t, t, t * 0.18, stroke=1, fill=1)
    q = t * 0.26
    pos = {1: [(0, 0)], 2: [(-q, q), (q, -q)], 3: [(-q, q), (0, 0), (q, -q)],
           4: [(-q, q), (q, q), (-q, -q), (q, -q)],
           5: [(-q, q), (q, q), (0, 0), (-q, -q), (q, -q)],
           6: [(-q, q), (q, q), (-q, 0), (q, 0), (-q, -q), (q, -q)]}[valeur]
    c.setFillColor(gris_ch)
    for dx, dy in pos:
        c.circle(cx + dx, cy + dy, t * 0.085, stroke=0, fill=1)


def _dessine_des(c, valeur, cx, cy, larg, haut, col, gris_ch):
    """Pose le ou les des au centre de la case, a l'echelle de SA case."""
    if valeur <= 6:
        t = min(haut * 0.80, larg * 0.42)
        _un_de(c, cx, cy, t, valeur, col, gris_ch)
    else:
        a, b = _DECOMP_DES[valeur]
        t = min(haut * 0.72, larg * 0.30)
        ecart = t * 0.62
        _un_de(c, cx - ecart, cy, t, a, col, gris_ch)
        _un_de(c, cx + ecart, cy, t, b, col, gris_ch)


def _dessiner_feuille(c, x0, y0, grilles, series, couleurs, titre_jeu="",
                      telephone="", style="eco", des=False):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_decor(c, x0, y0, couleurs)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, cadre, cases, rangee) in enumerate(CARTES):
        grille = grilles[gi]
        for ri in range(LIGNES):
            cy = MY((rangee[ri] + rangee[ri + 1]) / 2.0) - _T_CASE * 0.329
            cmil = MY((rangee[ri] + rangee[ri + 1]) / 2.0)
            chaut = (rangee[ri + 1] - rangee[ri]) / 1000.0 * FEUILLE_H
            for ci in range(3):
                val = grille[ri][ci]
                cx = MX((cases[ci] + cases[ci + 1]) / 2.0)
                clarg = (cases[ci + 1] - cases[ci]) / 1000.0 * FEUILLE_W
                if des and val <= 9:   # 🎲 jumeau CASINO
                    _dessine_des(c, val, cx, cmil, clarg, chaut,
                                 couleurs[gi], gris_ch)
                    continue
                if _sec:
                    _sec.chiffre_micro(c, val, cx, cy, _T_CASE, gris_ch, police_ch,
                                       epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch)
                    c.setFont(police_ch, _T_CASE)
                    c.drawCentredString(cx, cy, str(val))
        # ⭐ le numéro de série se pose JUSTE APRÈS SON « N° », dans le bandeau
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawString(MX(cases[0]) + 6.0 * mm, MY(rangee[0]) + 2.7 * mm,
                     "%06d" % series[gi])
        if telephone:
            c.setFont(POLICE, _T_TEL)
            c.drawRightString(MX(cases[3]) - 0.8 * mm, MY(rangee[0]) + 2.7 * mm,
                              telephone[:14])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(cadre[1]),
                                 MX(bord[1]) - MX(bord[0]),
                                 MY(cadre[0]) - MY(cadre[1]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=16, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="",
                des=False, page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(450000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()

    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)

        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        # ⭐ UNE COULEUR PAR CARTON, comme sur l'ancienne version.
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, couleurs,
                          titre_jeu, telephone, style=style, des=des)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


