def generer_pdf_casino(**kw):
    """🎲 WIN CASINO — le jumeau ou les numeros 1 a 9 vivent en vrais des.
    ⚠️ Il partage la planche du WIN : elle a change pour lui aussi."""
    kw["des"] = True
